import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;

    static class Matrix {
        long[][] data;
        int size;

        Matrix(int size) {
            this.size = size;
            data = new long[size][size];
        }

        static Matrix multiply(Matrix A, Matrix B) {
            Matrix C = new Matrix(A.size);
            for (int i = 0; i < A.size; ++i) {
                for (int j = 0; j < A.size; ++j) {
                    C.data[i][j] = 0;
                    for (int k = 0; k < A.size; ++k) {
                        C.data[i][j] += A.data[i][k] * B.data[k][j];
                    }
                    C.data[i][j] %= MOD_CONST;
                }
            }
            return C;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n_input = sc.nextLong();
        long m_input = sc.nextLong();

        int size = (int) m_input + 1;

        Matrix baseMat = new Matrix(size);
        Matrix identityMat = new Matrix(size);

        for (int i = 0; i <= m_input; ++i) {
            baseMat.data[i][i] = 1;
            baseMat.data[0][i] = 1;
        }

        for (int i = 0; i <= m_input; ++i) {
            identityMat.data[i][i] = 1;
        }

        long yVal = 1, yPow = 1;
        int levelIdx = 0;
        long totalCount = 0;

        while (yPow * m_input <= n_input) {
            yPow *= m_input;
            levelIdx++;
        }

        // Initialize biMatrices
        Matrix[][] biMatrices = new Matrix[levelIdx + 1][(int) m_input + 1];

        for (int t = 0; t <= levelIdx; ++t) {
            if (t > 0) {
                biMatrices[t][0] = biMatrices[t - 1][0];
                for (int i = 1; i <= m_input; ++i) {
                    biMatrices[t][0] = Matrix.multiply(biMatrices[t][0], biMatrices[t - 1][i]);
                }
            }
            for (int i = 1; i <= m_input; ++i) {
                biMatrices[t][i] = biMatrices[t][i - 1];
                // Swap rows and columns as in original code
                for (int j = m_input - 2; j >= 0; --j) {
                    for (int k = 0; k <= m_input; ++k) {
                        long temp = biMatrices[t][i].data[j][k];
                        biMatrices[t][i].data[j][k] = biMatrices[t][i].data[j + 1][k];
                        biMatrices[t][i].data[j + 1][k] = temp;
                    }
                }
                for (int j = m_input - 2; j >= 0; --j) {
                    for (int k = 0; k <= m_input; ++k) {
                        long temp = biMatrices[t][i].data[k][j];
                        biMatrices[t][i].data[k][j] = biMatrices[t][i].data[k][j + 1];
                        biMatrices[t][i].data[k][j + 1] = temp;
                    }
                }
            }
        }

        Matrix currentMat = identityMat;
        while (totalCount < n_input) {
            if (totalCount + yPow <= n_input) {
                totalCount += yPow;
                currentMat = Matrix.multiply(currentMat, biMatrices[levelIdx][0]);
                yVal = (yVal + 1) % m_input;
            } else {
                yPow /= m_input;
                levelIdx--;
            }
        }

        long finalSum = 0;
        for (int i = 0; i <= m_input; ++i) {
            finalSum = (finalSum + currentMat.data[i][(int) m_input]) % MOD_CONST;
        }
        System.out.println(finalSum);
        sc.close();
    }
}

